disagreements_145.dg8p_sql:
WITH last_stay AS (
  SELECT stay_id FROM icustays WHERE subject_id = 10018423 ORDER BY intime DESC LIMIT 1
), bp AS (
  SELECT c.valuenum, c.charttime, c.row_id
  FROM chartevents c
  JOIN d_items d ON c.itemid = d.itemid
  WHERE c.stay_id = (SELECT stay_id FROM last_stay)
    AND d.label IN ('non invasive blood pressure systolic','arterial blood pressure systolic','art bp systolic','manual blood pressure systolic left','manual blood pressure systolic right')
    AND c.valuenum IS NOT NULL
), f AS (
  SELECT valuenum FROM bp ORDER BY charttime ASC, row_id ASC LIMIT 1
), l AS (
  SELECT valuenum FROM bp ORDER BY charttime DESC, row_id DESC LIMIT 1
)
SELECT (SELECT valuenum FROM l) - (SELECT valuenum FROM f) AS sbp_change;

