  -
  (SELECT valuenum FROM chartevents WHERE stay_id = (SELECT stay_id FROM icustays WHERE subject_id=10019777 ORDER BY intime DESC LIMIT 1) AND itemid IN (220210,224688,224689,224690) ORDER BY charttime DESC LIMIT 1 OFFSET 1)
) AS difference;
